def _valid(n, deps, order):
    if sorted(order) != list(range(n)):
        return False
    pos = {t: i for i, t in enumerate(order)}
    return all(pos[b] < pos[a] for a, b in deps)

def test_basic():
    deps = [[1, 0], [2, 0], [3, 1], [3, 2]]
    assert _valid(4, deps, build_order(4, deps))

def test_cycle():
    assert build_order(2, [[0, 1], [1, 0]]) == []

def test_no_deps():
    assert _valid(3, [], build_order(3, []))

def test_self_loop():
    assert build_order(3, [[1, 0], [2, 2]]) == []

def test_long_chain():
    n = 5000
    deps = [[i + 1, i] for i in range(n - 1)]
    out = build_order(n, deps)
    assert out == list(range(n))
